)}@media(max-width:1150px){.stats-grid{grid-template-columns:repeat(2,1fr)}.charts-grid{grid-template-columns:1fr}}@media(max-width:620px){.stats-grid{grid-template-columns:1fr}.stat-card{min-height:auto}}
